diff --git a/apps/dsh_flutter/test/parity/cases/plugin_cards.dart b/apps/dsh_flutter/test/parity/cases/plugin_cards.dart
new file mode 100644
index 00000000..e25fd134
--- /dev/null
+++ b/apps/dsh_flutter/test/parity/cases/plugin_cards.dart
@@ -0,0 +1,244 @@
+import 'dart:async';
+
+import 'package:dsh_feature_plugins/dsh_feature_plugins.dart';
+import 'package:dsh_i18n/dsh_i18n.dart';
+import 'package:dsh_parity/dsh_parity.dart';
+import 'package:dsh_slots/dsh_slots.dart';
+import 'package:dsh_ui/dsh_ui.dart';
+import 'package:flutter/widgets.dart';
+import 'package:flutter_test/flutter_test.dart';
+
+import '../helpers/plugin_card_fixture.dart';
+
+final Map<String, ParityCase> pluginCardCases = {
+  'plugin-cards.manager': ParityCase(
+    widgets: [
+      'dsh_feature_plugins:PluginManagerPage loaded cards',
+      'dsh_ui:DshPluginCard',
+      'dsh_ui:DshPluginCardList',
+    ],
+    framed: false,
+    geometryProbe: pluginCardGeometryProbe,
+    notes: 'Actual manager with shared offline data. Published-bundle source runner required; no source-TS substitution. SVG image formats, highlight and sticky touch hover remain pending.',
+    build: (ctx) => PluginCardCaptureSurface(
+      scenario: (ctx.props['scenario'] as Map).cast<String, Object?>(),
+      i18n: DshI18n(DshLocale.fromTag(ctx.locale)),
+    ),
+  ),
+};
+
+/// Actual render boxes and public control state; this callback never pumps or
+/// sends input. It observes the same tree as the captured PNG before release.
+Map<String, Object?> pluginCardGeometryProbe(
+  WidgetTester tester,
+  ParityContext ctx,
+  RenderBox captureRoot,
+) {
+  final package = (ctx.props['scenario'] as Map)['package'] as Map;
+  final cardFinder = find.byKey(ValueKey('plugin-card-${package['name']}'));
+  final cards = cardFinder.evaluate().toList();
+
+  Map<String, Object?>? read(Element? element, {String? text}) {
+    if (element == null) return null;
+    final render = element.findRenderObject();
+    if (render is! RenderBox || !render.attached || !render.hasSize) {
+      return null;
+    }
+    final offset = render.localToGlobal(Offset.zero, ancestor: captureRoot);
+    final rect = offset & render.size;
+    return {
+      'bounds': [rect.left, rect.top, rect.width, rect.height],
+      'rawFlutterRect': {
+        'left': rect.left,
+        'top': rect.top,
+        'right': rect.right,
+        'bottom': rect.bottom,
+      },
+      'widgetType': element.widget.runtimeType.toString(),
+      'renderType': render.runtimeType.toString(),
+      'measurement': element.widget is DshChromeText
+          ? 'DshChromeText outer render/line box; not glyph ink or a stretched action'
+          : 'public widget outer RenderBox',
+      if (text != null) 'text': text,
+    };
+  }
+
+  Element? one(Finder finder) => finder.evaluate().firstOrNull;
+  Finder under(Finder finder) =>
+      find.descendant(of: cardFinder, matching: finder);
+  final card = cards.length == 1
+      ? tester.widget<DshPluginCard>(cardFinder)
+      : null;
+  final action = under(find.byKey(DshPluginCard.actionKey));
+  final actionElement = one(action);
+  final actionWidget = actionElement?.widget as DshButton?;
+  final frame = under(find.byKey(DshPluginCard.frameKey));
+  final defaultArtwork = find.descendant(
+    of: frame,
+    matching: find.byType(DshPluginDefaultArtwork),
+  );
+  final artwork =
+      one(defaultArtwork) ??
+      one(find.descendant(of: frame, matching: find.byType(Image)));
+  Element? textElement(String? value) => value == null
+      ? null
+      : one(
+          under(
+            find.byWidgetPredicate(
+              (widget) =>
+                  widget is DshChromeText &&
+                  (widget.data == value || widget.semanticsLabel == value),
+            ),
+          ),
+        );
+  final switchFinder = under(
+    find.byKey(ValueKey('plugin-switch-${package['name']}')),
+  );
+  final switchElement = one(switchFinder);
+  final switchWidget = switchElement?.widget as DshSwitch?;
+  FocusNode? actionFocus;
+  if (actionElement != null) {
+    final detector = one(
+      find.descendant(
+        of: action,
+        matching: find.byType(FocusableActionDetector),
+      ),
+    );
+    actionFocus = (detector?.widget as FocusableActionDetector?)?.focusNode;
+  }
+  final ring = one(
+    find.descendant(of: action, matching: find.byKey(DshButton.focusRingKey)),
+  );
+  final tags = under(find.byType(DshTag)).evaluate().map((element) {
+    final tag = element.widget as DshTag;
+    return {
+      ...?read(
+        element,
+        text: tag.child is DshChromeText
+            ? (tag.child as DshChromeText).data
+            : null,
+      ),
+      'tone': tag.tone.name,
+      'profile': tag.profile.name,
+    };
+  }).toList();
+  return {
+    'schema': 'dsh-plugin-card-geometry/1',
+    'coordinateBasis': {
+      'space': 'capture-root logical pixels; viewport aligned',
+      'origin': [0.0, 0.0],
+      'layoutViewport': [captureRoot.size.width, captureRoot.size.height],
+      'devicePixelRatio': ctx.density,
+      'measurement': 'RenderBox.localToGlobal(Offset.zero, ancestor: captureRoot) plus raw RenderBox.size',
+      'rounding': 'none',
+    },
+    'status': cards.length == 1 ? 'measured' : 'expected-one-card',
+    'geometrySemantics': {
+      'title': 'visible DshChromeText outer line box; compare separately with the source text-sized title DOM button',
+      'action': 'canonical stretched DshButton action/semantic hit box; source counterpart is the whole-card pseudo-element hit area, not the text-sized DOM button',
+      'innerCard': 'canonical card outer Stack including metadata; not a viewport or heading-row inference',
+      'rawRenderParagraph': 'not sampled',
+      'glyphInkBounds': 'not sampled',
+    },
+    'cardCount': cards.length,
+    'card': cards.length == 1 ? read(cards.single) : null,
+    'innerCard': read(one(under(find.byType(Stack)))),
+    'action': read(actionElement),
+    'title': read(textElement(card?.title), text: card?.title),
+    'description': read(
+      textElement(card?.description),
+      text: card?.description,
+    ),
+    'artworkFrame': read(one(frame)),
+    'artwork': read(artwork),
+    'artworkKind': artwork?.widget is DshPluginDefaultArtwork
+        ? 'native default/fallback artwork widget'
+        : artwork == null
+        ? null
+        : 'native Image widget; no DOM/SVG equivalence inferred',
+    'imageConfigured': card?.image != null,
+    'tags': tags,
+    'metadataError': read(
+      textElement(card?.metadataError),
+      text: card?.metadataError,
+    ),
+    'switch': switchWidget == null
+        ? null
+        : {
+            ...?read(switchElement),
+            'checked': switchWidget.value.toString(),
+            'value': switchWidget.value,
+            'disabled': switchWidget.onChanged == null,
+          },
+    'hover': actionWidget?.sourceHovered,
+    'focusedTitle': actionFocus?.hasPrimaryFocus,
+    'titleFocusVisible': actionElement == null ? null : ring != null,
+    'titleOutline': {
+      'focusRingPresent': actionElement == null ? null : ring != null,
+      'bounds': read(ring)?['bounds'],
+      'measurement': 'actual canonical native focus-ring widget presence/bounds; not a CSS pseudo-element assertion',
+    },
+    'focusMeasurement': 'actual card action FocusableActionDetector.focusNode.hasPrimaryFocus; visible native title text is measured separately from its stretched action',
+    'optionalParts': {
+      'descriptionPresent':
+          card?.description != null && card!.description!.isNotEmpty,
+      'metadataErrorPresent': card?.metadataError != null,
+      'tagCount': tags.length,
+    },
+  };
+}
+
+/// Full actual manager; no card layout, metric or paint is supplied by this
+/// fixture. The only outer paint is the normal application theme canvas.
+class PluginCardCaptureSurface extends StatefulWidget {
+  const PluginCardCaptureSurface({
+    super.key,
+    required this.scenario,
+    required this.i18n,
+    this.onFixture,
+  });
+  final Map<String, Object?> scenario;
+  final DshI18n i18n;
+  final void Function(SyntheticPluginCardFixture)? onFixture;
+
+  @override
+  State<PluginCardCaptureSurface> createState() =>
+      _PluginCardCaptureSurfaceState();
+}
+
+class _PluginCardCaptureSurfaceState extends State<PluginCardCaptureSurface> {
+  late final fixture = SyntheticPluginCardFixture(widget.scenario);
+  final slots = SlotRegistry();
+
+  @override
+  void initState() {
+    super.initState();
+    for (final slot in DshSlots.all) {
+      slots.declare(slot);
+    }
+    widget.onFixture?.call(fixture);
+  }
+
+  @override
+  void dispose() {
+    unawaited(fixture.dispose());
+    super.dispose();
+  }
+
+  @override
+  Widget build(BuildContext context) => ColoredBox(
+    key: const ValueKey('plugin-cards-capture'),
+    color: context.dsh.bgBase,
+    child: DefaultTextStyle(
+      style: context.dsh
+          .textStyle('--dsw-font-s-14')
+          .copyWith(color: context.dsh.labelPrimary),
+      child: PluginManagerPage(
+        model: fixture.manager,
+        market: fixture.market,
+        slots: slots,
+        i18n: widget.i18n,
+      ),
+    ),
+  );
+}
diff --git a/apps/dsh_flutter/test/parity/helpers/plugin_card_fixture.dart b/apps/dsh_flutter/test/parity/helpers/plugin_card_fixture.dart
new file mode 100644
index 00000000..964fc41f
--- /dev/null
+++ b/apps/dsh_flutter/test/parity/helpers/plugin_card_fixture.dart
@@ -0,0 +1,127 @@
+import 'dart:convert';
+
+import 'package:dsh_models/dsh_models.dart';
+import 'package:dsh_models/testing.dart';
+
+import 'plugins_preview_fixture.dart';
+
+/// Single synthetic data source shared by Dart, the plan builder and the actual
+/// published-bundle browser host. No native asset/file reads are needed.
+const pluginCardScenarioJson = r'''
+{
+  "schema": "dsh-plugin-card-scenarios/1",
+  "basePackage": {
+    "name": "@synthetic/card-default", "official": false,
+    "availability": "profile", "installed": true, "enabled": true,
+    "optional": false, "removable": true, "version": "1.0.0",
+    "meta": {
+      "title": {"en": "Synthetic plugin", "zh": "合成插件"},
+      "description": {"en": "A synthetic package for loaded-card checks.", "zh": "用于已加载卡片核对的合成扩展包。"}
+    },
+    "rows": [], "overrides": []
+  },
+  "scenarios": [
+    {"id": "default", "package": {}, "expected": {"enabled": true, "locked": false, "tagKeys": []}},
+    {"id": "no-description", "package": {"name": "@synthetic/card-no-description", "meta": {"title": {"en": "No description", "zh": "没有说明"}}}, "expected": {"enabled": true, "locked": false, "tagKeys": []}},
+    {"id": "long-tags", "package": {
+      "name": "@deepseek-ai/dsh-experimental-synthetic-card", "availability": "missing", "enabled": false,
+      "error": {"code": "operation-error", "diagnostic": "Synthetic unavailable files"},
+      "installTarget": {"spec": "@synthetic/card@2.0.0", "version": "2.0.0"},
+      "meta": {
+        "title": {"en": "A deliberately long localized synthetic plugin title with adjacent status tags", "zh": "带有相邻状态标签的故意加长本地化合成插件标题用于核对自然换行"},
+        "description": {"en": "A deliberately long synthetic description that must retain the source single-line clamp while the title and tags wrap naturally.", "zh": "这是一段故意加长的合成说明，应当保留原版单行截断，同时允许标题和状态标签自然换行。"}
+      }
+    }, "expected": {"enabled": false, "locked": false, "tagKeys": ["statusBeta", "statusProblem", "statusMissingFiles", "statusUpdateAvailable"]}},
+    {"id": "problem-enabled", "package": {"name": "@synthetic/card-problem-enabled", "error": {"code": "operation-error", "diagnostic": "Synthetic enabled package failure"}}, "expected": {"enabled": true, "locked": false, "tagKeys": ["statusProblem"]}},
+    {"id": "metadata-error", "package": {"name": "@synthetic/card-metadata-error", "meta": {"title": {"en": "Metadata error", "zh": "元数据错误"}, "description": {"en": "The metadata diagnostic owns its own line.", "zh": "元数据诊断保留独立文本行。"}, "error": "Synthetic metadata diagnostic\nwith a second line"}}, "expected": {"enabled": true, "locked": false, "tagKeys": [], "metadataError": true}},
+    {"id": "busy", "busy": true, "package": {"name": "@synthetic/card-busy"}, "expected": {"enabled": true, "locked": true, "tagKeys": []}},
+    {"id": "read-only", "package": {"name": "@synthetic/card-read-only", "readOnlyReason": "management-required"}, "expected": {"enabled": true, "locked": true, "tagKeys": []}},
+    {"id": "error-disabled", "package": {"name": "@synthetic/card-error-disabled", "enabled": false, "error": {"code": "operation-error", "diagnostic": "Synthetic disabled package failure"}}, "expected": {"enabled": false, "locked": true, "tagKeys": ["statusProblem"]}},
+    {"id": "missing-recovery", "package": {"name": "@synthetic/card-missing-recovery", "availability": "missing", "installed": false, "enabled": false, "error": {"code": "operation-error", "diagnostic": "Synthetic missing package"}, "installTarget": {"spec": "@synthetic/card@2.0.0", "version": "2.0.0"}}, "expected": {"enabled": false, "locked": false, "tagKeys": ["statusProblem", "statusNotInstalled"]}},
+    {"id": "refused-toggle", "refuseToggle": true, "package": {"name": "@synthetic/card-refused-toggle"}, "expected": {"enabled": true, "locked": false, "tagKeys": []}},
+    {"id": "image-failed", "package": {"name": "@synthetic/card-image-failed", "meta": {"title": {"en": "Failed artwork", "zh": "加载失败的图像"}, "description": {"en": "Invalid data PNG falls back without a network request.", "zh": "无效的数据图像直接回退，不发起网络请求。"}, "icon": "data:image/png;base64,AAAA"}}, "expected": {"enabled": true, "locked": false, "tagKeys": []}}
+  ]
+}
+''';
+
+final Map<String, Map<String, Object?>> pluginCardScenarios = () {
+  final data = jsonDecode(pluginCardScenarioJson) as Map<String, dynamic>;
+  if (data['schema'] != 'dsh-plugin-card-scenarios/1') {
+    throw StateError('Unexpected loaded-card fixture schema');
+  }
+  final base = (data['basePackage'] as Map).cast<String, Object?>();
+  return {
+    for (final raw in data['scenarios'] as List)
+      (raw as Map)['id'] as String: {
+        ...raw.cast<String, Object?>(),
+        'package': {
+          ...base,
+          ...(raw['package'] as Map).cast<String, Object?>(),
+        },
+      },
+  };
+}();
+
+/// Offline business adapter around the existing real manager fixture. Page,
+/// card, switch, navigation and model actions remain the actual implementations.
+class SyntheticPluginCardFixture {
+  SyntheticPluginCardFixture(this.scenario) {
+    _package = Map<String, Object?>.from(
+      (scenario['package'] as Map).cast<String, Object?>(),
+    );
+    enabled = _package['enabled'] as bool;
+    host.handlers['pluginManager/listBundles'] = (_) => [
+      {..._package, 'enabled': enabled},
+    ];
+    host.handlers['pluginManager/listPlugins'] = (_) => <Object?>[];
+    host.handlers['pluginInventory/list'] = (_) => {
+      'managementAvailable': true,
+      'entries': <Object?>[],
+      'agentPresets': <Object?>[],
+    };
+    host.handlers['pluginManager/setBundleEnabled'] = (args) {
+      attempts++;
+      requestedValues.add(args['enabled'] as bool);
+      if (scenario['refuseToggle'] == true) {
+        refusals++;
+        return {
+          'changed': false,
+          'application': 'failed',
+          'stage': 'enable',
+          'target': packageName,
+          'error': {
+            'code': 'operation-error',
+            'diagnostic': 'Synthetic toggle refused',
+          },
+        };
+      }
+      enabled = args['enabled'] as bool;
+      return {
+        'changed': true,
+        'application': 'applied',
+        'stage': 'enable',
+        'target': packageName,
+      };
+    };
+    if (scenario['busy'] == true) manager.busy.add(packageName);
+  }
+
+  factory SyntheticPluginCardFixture.fromId(String id) =>
+      SyntheticPluginCardFixture(
+        pluginCardScenarios[id] ??
+            (throw ArgumentError.value(id, 'id', 'Unknown card scenario')),
+      );
+
+  final Map<String, Object?> scenario;
+  final _base = SyntheticPluginsPreview();
+  late final Map<String, Object?> _package;
+  late bool enabled;
+  int attempts = 0, refusals = 0;
+  final requestedValues = <bool>[];
+  FakeHost get host => _base.host;
+  PluginManagerModel get manager => _base.manager;
+  PluginMarketModel get market => _base.market;
+  String get packageName => _package['name'] as String;
+  Future<void> load() => manager.load();
+  Future<void> dispose() => _base.dispose();
+}
diff --git a/apps/dsh_flutter/test/parity/plugin_cards_fixture_test.dart b/apps/dsh_flutter/test/parity/plugin_cards_fixture_test.dart
new file mode 100644
index 00000000..b5755e12
--- /dev/null
+++ b/apps/dsh_flutter/test/parity/plugin_cards_fixture_test.dart
@@ -0,0 +1,135 @@
+import 'dart:io';
+
+import 'package:dsh_i18n/dsh_i18n.dart';
+import 'package:dsh_theme/testing.dart';
+import 'package:dsh_ui/dsh_ui.dart';
+import 'package:flutter/widgets.dart';
+import 'package:flutter_test/flutter_test.dart';
+
+import 'cases/plugin_cards.dart';
+import 'helpers/plugin_card_fixture.dart';
+
+void main() {
+  test('compiled scenario data has exactly the source plan branches', () {
+    expect(pluginCardScenarios.keys, {
+      'default',
+      'no-description',
+      'long-tags',
+      'problem-enabled',
+      'metadata-error',
+      'busy',
+      'read-only',
+      'error-disabled',
+      'missing-recovery',
+      'refused-toggle',
+      'image-failed',
+    });
+    expect(
+      (pluginCardScenarios['image-failed']!['package'] as Map)['meta'],
+      containsPair('icon', 'data:image/png;base64,AAAA'),
+    );
+  });
+
+  for (final id in pluginCardScenarios.keys) {
+    testWidgets('actual manager scenario $id exposes source state', (t) async {
+      t.view.physicalSize = const Size(390, 900);
+      t.view.devicePixelRatio = 1;
+      addTearDown(t.view.reset);
+      SyntheticPluginCardFixture? fixture;
+      final scenario = pluginCardScenarios[id]!;
+      await t.pumpWidget(
+        dshTestApp(
+          PluginCardCaptureSurface(
+            scenario: scenario,
+            i18n: const DshI18n(DshLocale.en),
+            onFixture: (value) => fixture = value,
+          ),
+        ),
+      );
+      await t.pumpAndSettle();
+      final actual = fixture!;
+      final expected = scenario['expected'] as Map;
+      final card = find.byKey(ValueKey('plugin-card-${actual.packageName}'));
+      expect(card, findsOneWidget);
+      final control = find.byKey(
+        ValueKey('plugin-switch-${actual.packageName}'),
+      );
+      final switcher = t.widget<DshSwitch>(control);
+      expect(switcher.value, expected['enabled']);
+      expect(switcher.onChanged == null, expected['locked']);
+      const i18n = DshI18n(DshLocale.en);
+      for (final key in expected['tagKeys'] as List) {
+        expect(
+          find.text(i18n.t('pluginManager', key as String)),
+          findsOneWidget,
+        );
+      }
+      if (id == 'no-description') {
+        expect(t.widget<DshPluginCard>(card).description, isNull);
+      }
+      if (id == 'metadata-error') {
+        expect(
+          t.widget<DshPluginCard>(card).metadataError,
+          contains('Synthetic metadata diagnostic\nwith a second line'),
+        );
+      }
+      if (expected['locked'] == true || id == 'refused-toggle') {
+        await t.tap(control);
+        await t.pumpAndSettle();
+        expect(actual.attempts, id == 'refused-toggle' ? 1 : 0);
+        expect(actual.refusals, id == 'refused-toggle' ? 1 : 0);
+        expect(actual.enabled, expected['enabled']);
+        expect(find.text(i18n.t('pluginManager', 'backToList')), findsNothing);
+      }
+      expect(t.takeException(), isNull);
+      await t.pumpWidget(const SizedBox());
+      await t.pumpAndSettle();
+    });
+  }
+
+  test('source plan helper remains a single compiled JSON source', () {
+    final file = File('test/parity/helpers/plugin_card_fixture.dart');
+    final matches = RegExp(
+      "const pluginCardScenarioJson = r'''\\n(.*?)\\n''';",
+      dotAll: true,
+    ).allMatches(file.readAsStringSync());
+    expect(matches.length, 1);
+    expect(matches.single.group(1)!.trim(), pluginCardScenarioJson.trim());
+  });
+
+  for (final brightness in Brightness.values) {
+    for (final locale in [DshLocale.en, DshLocale.zh]) {
+      for (final width in [390.0, 800.0]) {
+        for (final density in [1.0, 2.625]) {
+          testWidgets(
+            'long localized actual card ${brightness.name}/${locale.name}/$width/$density',
+            (t) async {
+              t.view.physicalSize = Size(width * density, 900 * density);
+              t.view.devicePixelRatio = density;
+              addTearDown(t.view.reset);
+              await t.pumpWidget(
+                dshTestApp(
+                  PluginCardCaptureSurface(
+                    scenario: pluginCardScenarios['long-tags']!,
+                    i18n: DshI18n(locale),
+                  ),
+                  brightness: brightness,
+                ),
+              );
+              await t.pumpAndSettle();
+              final card = t.widget<DshPluginCard>(find.byType(DshPluginCard));
+              final metadata =
+                  (pluginCardScenarios['long-tags']!['package'] as Map)['meta']
+                      as Map;
+              expect(card.title, (metadata['title'] as Map)[locale.name]);
+              expect(card.tags.length, 4);
+              expect(t.takeException(), isNull);
+              await t.pumpWidget(const SizedBox());
+              await t.pumpAndSettle();
+            },
+          );
+        }
+      }
+    }
+  }
+}
diff --git a/apps/dsh_flutter/test/parity/plugin_cards_geometry_test.dart b/apps/dsh_flutter/test/parity/plugin_cards_geometry_test.dart
new file mode 100644
index 00000000..f3996a67
--- /dev/null
+++ b/apps/dsh_flutter/test/parity/plugin_cards_geometry_test.dart
@@ -0,0 +1,200 @@
+import 'dart:io';
+
+import 'package:dsh_parity/dsh_parity.dart';
+import 'package:dsh_ui/dsh_ui.dart';
+import 'package:flutter/widgets.dart';
+import 'package:flutter_test/flutter_test.dart';
+
+import 'cases/plugin_cards.dart';
+import 'helpers/plugin_card_fixture.dart';
+
+void main() {
+  late Directory output;
+  late List<ParityFontFace> fonts;
+  setUpAll(() async {
+    output = Directory.systemTemp.createTempSync('plugin_card_geometry_');
+    fonts = await loadParityFonts(findParityFontsManifest());
+  });
+  tearDownAll(() => output.deleteSync(recursive: true));
+
+  for (final sample in [
+    (id: 'default', state: 'press', theme: 'light', locale: 'en', density: 1.0),
+    (id: 'default', state: 'focus', theme: 'dark', locale: 'en', density: 1.0),
+    (
+      id: 'no-description',
+      state: 'idle',
+      theme: 'light',
+      locale: 'en',
+      density: 1.0,
+    ),
+    (
+      id: 'long-tags',
+      state: 'idle',
+      theme: 'dark',
+      locale: 'zh-CN',
+      density: 2.625,
+    ),
+    (
+      id: 'metadata-error',
+      state: 'idle',
+      theme: 'light',
+      locale: 'en',
+      density: 1.0,
+    ),
+    (
+      id: 'image-failed',
+      state: 'idle',
+      theme: 'dark',
+      locale: 'en',
+      density: 1.0,
+    ),
+  ]) {
+    testWidgets('actual Card inner measurement ${sample.id}/${sample.state}', (
+      t,
+    ) async {
+      final scenario = pluginCardScenarios[sample.id]!;
+      final package = scenario['package'] as Map;
+      final key =
+          'components.plugin-card.geometry-${sample.id}-${sample.state}.${sample.theme}';
+      Rect? observedBeforeScreenshot;
+      final base = pluginCardCases['plugin-cards.manager']!;
+      final metadata = await captureParityCase(
+        t,
+        entry: {
+          'key': key,
+          'case': {
+            'id': key,
+            'kind': 'plugin-cards.manager',
+            'theme': sample.theme,
+            'locale': sample.locale,
+            'viewport': {
+              'width': 390,
+              'height': 900,
+              'density': sample.density,
+            },
+            'capture': {'crop': 'viewport'},
+          },
+          'variant': {
+            'id': 'default',
+            'name': sample.state,
+            'props': {'scenarioId': sample.id, 'scenario': scenario},
+            'interactions': [
+              if (sample.state != 'idle')
+                {
+                  'type': sample.state == 'focus'
+                      ? 'focus-by-tab'
+                      : sample.state,
+                  'target': 'plugin-card-${package['name']}',
+                },
+            ],
+          },
+        },
+        mapping: ParityCase(
+          widgets: base.widgets,
+          build: base.build,
+          framed: base.framed,
+          geometryProbe: base.geometryProbe,
+          notes: base.notes,
+          settle: base.settle,
+          interact: (tester, ctx) async {
+            observedBeforeScreenshot = tester.getRect(
+              find.byKey(ValueKey('plugin-card-${package['name']}')),
+            );
+          },
+        ),
+        fixtures: const {},
+        outputDir: output,
+        runInfo: const {},
+        fonts: fonts,
+        framed: base.framed,
+      );
+      final geometry = metadata['componentGeometry'] as Map;
+      expect(geometry['schema'], 'dsh-plugin-card-geometry/1');
+      expect(geometry['status'], 'measured');
+      expect(geometry['cardCount'], 1);
+      final actual = observedBeforeScreenshot!;
+      expect((geometry['card'] as Map)['bounds'], [
+        actual.left,
+        actual.top,
+        actual.width,
+        actual.height,
+      ]);
+      expect(
+        (geometry['innerCard'] as Map)['bounds'],
+        (geometry['card'] as Map)['bounds'],
+      );
+      expect(
+        (geometry['action'] as Map)['bounds'],
+        (geometry['card'] as Map)['bounds'],
+      );
+      expect((geometry['coordinateBasis'] as Map)['rounding'], 'none');
+      expect(
+        (geometry['coordinateBasis'] as Map)['devicePixelRatio'],
+        sample.density,
+      );
+      expect(
+        (geometry['switch'] as Map)['checked'],
+        package['enabled'].toString(),
+      );
+      expect((geometry['switch'] as Map)['disabled'], false);
+      expect((geometry['title'] as Map)['text'], isNotEmpty);
+      expect((geometry['title'] as Map)['widgetType'], 'DshChromeText');
+      expect(
+        (geometry['title'] as Map)['measurement'],
+        contains('outer render/line box'),
+      );
+      expect(
+        (((geometry['title'] as Map)['bounds'] as List)[2] as num) <
+            (((geometry['action'] as Map)['bounds'] as List)[2] as num),
+        isTrue,
+      );
+      expect(
+        (geometry['geometrySemantics'] as Map)['action'],
+        contains('whole-card pseudo-element'),
+      );
+      expect(
+        (geometry['geometrySemantics'] as Map)['glyphInkBounds'],
+        'not sampled',
+      );
+      expect((geometry['artworkFrame'] as Map)['bounds'], hasLength(4));
+      if (sample.state == 'press') {
+        // The actual release opens detail after the PNG and probe. Geometry
+        // still describes the list card, not that later route/view.
+        expect(find.byType(DshPluginCard), findsNothing);
+        expect(geometry['focusedTitle'], isTrue);
+      }
+      if (sample.state == 'focus') {
+        expect(geometry['focusedTitle'], isTrue);
+        expect(geometry['titleFocusVisible'], isTrue);
+        expect((geometry['titleOutline'] as Map)['bounds'], hasLength(4));
+      }
+      if (sample.id == 'no-description') {
+        expect(geometry['description'], isNull);
+        expect(geometry['metadataError'], isNull);
+        expect(geometry['tags'], isEmpty);
+      }
+      if (sample.id == 'long-tags') {
+        final tags = geometry['tags'] as List;
+        expect(tags, hasLength(4));
+        expect(tags.every((tag) => (tag as Map)['bounds'] is List), isTrue);
+        final width =
+            ((geometry['artworkFrame'] as Map)['bounds'] as List)[2] as double;
+        expect(width, isNot(width.roundToDouble()));
+      }
+      if (sample.id == 'metadata-error') {
+        expect(
+          (geometry['metadataError'] as Map)['text'],
+          contains('Synthetic metadata diagnostic\nwith a second line'),
+        );
+      }
+      if (sample.id == 'image-failed') {
+        expect(geometry['imageConfigured'], isTrue);
+        expect(
+          geometry['artworkKind'],
+          'native default/fallback artwork widget',
+        );
+        expect((geometry['artwork'] as Map)['bounds'], hasLength(4));
+      }
+    });
+  }
+}
diff --git a/apps/dsh_flutter/test/parity/plugin_cards_main.dart b/apps/dsh_flutter/test/parity/plugin_cards_main.dart
